INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('wumahqfqqduzirk2xt4wumahn024bkbw', '2025-Q4', 'Dez/2025', '2025-12-14T21:57'::timestamptz, 'José Duarte Tavares', 'jose duarte tavares', 'PHARUS', 'Rodrigo Lunardi', 7.0, 'Neutro', 10.0, 10.0, 5.0, NULL, 'Sim, em grande parte', NULL, NULL, NULL, NULL, 'Estou no início de minha jornada, implementando os primeiros mecanismos de renda sintética e leilão serial. Com certeza a simples obtenção dos resultados esperados nesses 12 meses já me  tornará confortável para oferecer nota 9 ou 10.', NULL, 'Que os resultados definidos no plano sejam atingidos, comprovando-se realmente superiores a outras alternativas existentes de ganho de capital para construção de patrimônio, visando o valor almejado de renda passiva.', 'Não, no momento.', NULL, NULL, 'nova jornada (backoffice/QV360)', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus', 'wumahqfqqduzirk2xt4wumahn024bkbw', 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUD