INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('yqkiurpadjnp3n57oi6bxqeusyqkiurp', '2025-Q4', 'Dez/2025', '2025-12-15T11:51'::timestamptz, 'Paulo Roberto Rui Arantes', 'paulo roberto rui arantes', 'PHARUS', 'Gabriel Oliveira', 8.0, 'Neutro', 10.0, 9.0, 2.0, NULL, 'Sim, em grande parte', NULL, NULL, NULL, NULL, 'Minha experiência está sendo muito boa ultimamente. Minha nota se deve ao contexto geral onde nos primeiros meses senti que não consegui abstrair o máximo do programa, parte disso por minha culpa. Meu assessor está sempre disponível e me assessora muito bem. A plataforma nova da quarta via, na minha opinião poderia ser aprimorada já que tive dificuldades usá-la. No geral está sendo muito boa a experiência', NULL, 'Sendo bem prático, faria uma conta simples do valor a investir no programa e a previsão concreta do retorno que teria usando as estratégias e facilidades oferecidas pela 4via e chegando a um resultado positivo', 'já falado nas perguntas anteriores', NULL, NULL, 'nova jornada (backoffice/QV360)', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus', 'yqkiurpadjnp3n57oi6bxqeusyqkiurp', 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUD