INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('raevkcdkala259e914fv9zt0tifraevk', '2025-Q4', 'Dez/2025', '2025-12-16T15:49'::timestamptz, 'Larissa de Aguiar Mesquita Xavier', 'larissa de aguiar mesquita xavier', 'PHARUS', NULL, 9.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', NULL, NULL, 'No meu círculo familiar atualmente não existem clientes considerados em potencial. O que mais me agradou é a maneira consciente como as coisas são conduzidas, pé no chão. Contudo, sinto falta de entrar em mais programas de alavancagem(crescimento em geral) ainda no primeiro ano(achei lento).', 'Participar de mais Aplicações (simultâneas). Foram mais de 6 meses até aparecer a 1ª oportunidade.', 'Apenas isso que foquei: entenda, se tiver uma previsão de aplicação em 12 meses, eu vou abrir mão de outras coisas e focar nas aplicações. Ex: no 1º, no PHARUS, você pode aplicar de R$0,00 até "limite definido pela equipe estratégica", isso nos dá um norte. Quantos clientes vocês tem que ganham muito, gastam muito e tem patrimônio incompatível? Vocês não precisam determinar, mas ao menos bimestral (não sei), ofertar aplicações que possam fazer sentido (levando em conta a reserva mas também o perfil do seu cliente). Vou deixar melhor explicado com meu estrategista.', NULL, NULL, 'legado', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus 2', 'raevkcdkala259e914fv9zt0tifraevk', 'aba PHARUS da planilha', NULL) ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
