INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('5cu7zd8kudexihj5cu7zd2pr1pj8nszk', '2025-Q4', 'Dez/2025', '2026-01-07T10:14'::timestamptz, 'Lenon Mazetto', 'lenon mazetto', 'PHARUS', NULL, 4.0, 'Detrator', 5.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', NULL, 'Estive pensando, mas o anúncio de vocês seria para que um médico que ganhasse R$ 7.000,00 por mês chegaria a ter um rendimento de R$ 7.000,00 por mês após 7 anos, claro, implementando as orientações de vocês. Certo? Mas como isso seria possível tendo que pagar mensalmente para vocês cerca de R$ 2.500,00 e ainda arcar com o custo de vida dele? Eu não tenho visto, nem de perto, uma estratégia dessas sendo aplicada a mim. Daí o meu descontentamento.', NULL, 'Perceber progressões e ter esclarecimentos das dúvidas apresentadas na minha resposta anterior.', 'Por enquanto, apenas ao fato de o investimento em crédito verde oferecido por vocês não estar creditando os rendimentos mensais em minha conta.', NULL, NULL, 'legado', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus 2', '5cu7zd8kudexihj5cu7zd2pr1pj8nszk', 'aba PHARUS da planilha', NULL) ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffic